select o.order_id,o.customer_id,c.customer_unique_id,o.order_status,o.order_purchase_timestamp,o.order_approved_at,o.order_delivered_carrier_date,o.order_delivered_customer_date,o.order_estimated_delivery_date,p.payment_total,p.payment_count,p.max_installments,p.primary_payment_type,r.average_review_score,coalesce(r.review_count,0) review_count,coalesce(r.has_review,false) has_review,coalesce(r.has_comment,false) has_comment,r.latest_review_date,datediff(hour,o.order_purchase_timestamp,o.order_approved_at) approval_hours,datediff(day,o.order_approved_at,o.order_delivered_carrier_date) carrier_handoff_days,datediff(day,o.order_purchase_timestamp,o.order_delivered_customer_date) actual_delivery_days,datediff(day,o.order_purchase_timestamp,o.order_estimated_delivery_date) estimated_delivery_days,datediff(day,o.order_estimated_delivery_date,o.order_delivered_customer_date) delivery_variance_days,case when o.order_delivered_customer_date>o.order_estimated_delivery_date then true else false end is_late_delivery,case when h.holiday_date is not null then true else false end is_purchase_holiday,h.holiday_name,c.customer_zip_code_prefix,c.customer_city,c.customer_state from {{ ref('stg_orders') }} o left join {{ ref('stg_customers') }} c on o.customer_id=c.customer_id left join {{ ref('int_payments_by_order') }} p on o.order_id=p.order_id left join {{ ref('int_reviews_by_order') }} r on o.order_id=r.order_id left join {{ ref('stg_holidays') }} h on cast(o.order_purchase_timestamp as date)=h.holiday_date
